const sourceScene = resolveSourceScene(stage);
if (sourceScene) {
  // Environmental threats never become a fallback army. Rendering reuses only an exact source identity.
  const threat = [...availableBosses, ...availableMonsters, availableWorldBoss].find(e => e?.name === sourceScene.threatName);
  return { monsters: [], bosses: threat ? [threat] : [], worldBoss: null, sourceSceneId: sourceScene.sourceSceneId };
}

this.actionPhase = this.sourceScene ? 'move' : 'action';
this.selectedAction = this.sourceScene ? null : 'simple';
if (this.sourceScene) this.calculateMovementRange();

if (this.sourceScene) {
  const s = this.sourceScene;
  return `${lang === 'fr' ? 'Commandes de mission' : 'Mission commands'} ${s.done.size}/${this.objectiveTarget} · ${s.turns}/${s.definition.turnLimit}`;
}

import { resolveSourceScene } from '../game/sourceSceneStages.js';
import SourceScenePanel from './SourceScenePanel.jsx';
import { drawSourceSceneBackdrop } from '../game/sourceScenePresentation.js';

const sourceScene = stage.mode === 'Tactics' ? engineRef.current?.getSourceSceneState?.() : null;
const handleSourceSceneCommand = (id, token) => {
  if (sessionPausedRef.current || battleCompleted || preMatchLocked || opponentHasCommand) return;
  const engine = engineRef.current;
  if (engine?.triggerSourceSceneAction?.(id, token)) { setSelectedAction(null); setTeamState([...engine.heroes]); }
};
